const { Given, When, Then } = require('@cucumber/cucumber');
const assert = require('node:assert');

// --- Background ---

Given('the app is loaded', function () {
  // Already loaded by the Before hook in world.js
});

// --- Given helpers ---

Given('the user has a todo titled {string}', function (title) {
  this.createTodo(title);
});

Given('the user has a completed todo titled {string}', function (title) {
  this.createTodo(title);
  this.toggleNthTodo(1);
});

Given('the user creates a todo titled {string}', function (title) {
  this.createTodo(title);
});

Given('the user has an active todo titled {string}', function (title) {
  this.createTodo(title);
});

Given('all todos are completed', function () {
  this.createTodo('Buy milk');
  this.createTodo('Walk dog');
  this.toggleNthTodo(1);
  this.toggleNthTodo(2);
});

Given('the user completes the first todo', function () {
  this.toggleNthTodo(1);
});

Given('the user filters by {string}', function (filter) {
  this.navigate('#/' + filter.toLowerCase());
});

Given('localStorage contains a todo titled {string}', function (title) {
  // Write directly to localStorage
  const todos = [{ id: 1, title: title, completed: false }];
  this.localStorage.setItem('todos-vanilla', JSON.stringify(todos));
});

// --- When actions ---

When('the user types {string} in the new todo input', function (text) {
  const input = this.document.querySelector('.new-todo');
  input.value = text;
});

When('presses Enter', function () {
  const event = new this.window.Event('keydown', {
    key: 'Enter',
    keyCode: 13,
    which: 13,
    bubbles: true,
  });
  const input = this.document.querySelector('.new-todo') ||
    this.document.querySelector('.edit');
  if (input) {
    input.dispatchEvent(event);
  }
});

When('presses Escape', function () {
  const input = this.document.querySelector('.edit');
  if (input) {
    const event = new this.window.Event('keydown', {
      key: 'Escape',
      keyCode: 27,
      which: 27,
      bubbles: true,
    });
    input.dispatchEvent(event);
  }
});

When('the user creates a todo titled {string}', function (title) {
  this.createTodo(title);
});

When('the user toggles the todo', function () {
  // Toggle the first (and only expected) todo
  this.toggleNthTodo(1);
});

When('the user toggles the first todo', function () {
  this.toggleNthTodo(1);
});

When('the user toggles the second todo', function () {
  this.toggleNthTodo(2);
});

When('the user toggles one todo', function () {
  this.toggleNthTodo(1);
});

When('the user marks all todos as complete', function () {
  const checkbox = this.document.querySelector('.toggle-all');
  if (checkbox) {
    checkbox.checked = true;
    checkbox.dispatchEvent(new this.window.Event('change', { bubbles: true }));
  }
});

When('the user destroys the todo', function () {
  const destroyBtn = this.document.querySelector('.destroy');
  if (destroyBtn) {
    destroyBtn.dispatchEvent(new this.window.Event('click', { bubbles: true }));
  }
});

When('the user clears completed todos', function () {
  const btn = this.document.querySelector('.clear-completed');
  if (btn) {
    btn.dispatchEvent(new this.window.Event('click', { bubbles: true }));
  }
});

When('the user edits the todo to {string}', function (newTitle) {
  // Double-click the label to enter editing
  const label = this.document.querySelector('.todo-list li:first-child label');
  if (label) {
    label.dispatchEvent(new this.window.Event('dblclick', { bubbles: true }));
  }
  // Set the edit input value
  const editInput = this.document.querySelector('.todo-list li:first-child .edit');
  if (editInput) {
    editInput.value = newTitle;
  }
});

When('the edit input loses focus', function () {
  const editInput = this.document.querySelector('.todo-list li:first-child .edit');
  if (editInput) {
    editInput.dispatchEvent(new this.window.Event('blur', { bubbles: true }));
  }
});

When('the user filters by {string}', function (filter) {
  this.navigate('#/' + filter.toLowerCase());
});

When('the app is reloaded', function () {
  // Capture current localStorage, re-load the app
  const savedData = this.localStorage.getItem('todos-vanilla');
  this.disposeApp();
  this.loadApp();
  // Restore saved data
  if (savedData !== null) {
    this.localStorage.setItem('todos-vanilla', savedData);
  }
  // Re-init: dispatch load events so the app re-reads localStorage
  this.window.dispatchEvent(new this.window.Event('load'));
});

When('the user starts editing the todo', function () {
  const label = this.document.querySelector('.todo-list li:first-child label');
  if (label) {
    label.dispatchEvent(new this.window.Event('dblclick', { bubbles: true }));
  }
});

// --- Then assertions ---

Then('the main section is not visible', function () {
  const main = this.document.querySelector('.main');
  // Hidden via display:none or no element / hidden class
  if (main) {
    const style = this.window.getComputedStyle(main);
    assert.strictEqual(style.display, 'none', 'main section should be hidden');
  }
});

Then('the footer is not visible', function () {
  const footer = this.document.querySelector('.footer');
  if (footer) {
    const style = this.window.getComputedStyle(footer);
    assert.strictEqual(style.display, 'none', 'footer should be hidden');
  }
});

Then('the main section is visible', function () {
  const main = this.document.querySelector('.main');
  assert.ok(main, 'main section should exist');
  const style = this.window.getComputedStyle(main);
  assert.notStrictEqual(style.display, 'none', 'main section should be visible');
});

Then('the footer is visible', function () {
  const footer = this.document.querySelector('.footer');
  assert.ok(footer, 'footer should exist');
  const style = this.window.getComputedStyle(footer);
  assert.notStrictEqual(style.display, 'none', 'footer should be visible');
});

Then('the todo list displays {int} item', function (count) {
  const items = this.document.querySelectorAll('.todo-list li');
  assert.strictEqual(items.length, count, `expected ${count} todo items, got ${items.length}`);
});

Then('the todo list displays {int} items', function (count) {
  const items = this.document.querySelectorAll('.todo-list li');
  assert.strictEqual(items.length, count, `expected ${count} todo items, got ${items.length}`);
});

Then('the todo list displays no items', function () {
  const items = this.document.querySelectorAll('.todo-list li');
  assert.strictEqual(items.length, 0, `expected 0 todo items, got ${items.length}`);
});

Then('the item shows {string}', function (title) {
  const items = this.document.querySelectorAll('.todo-list li label');
  // Find first visible item (not hidden by filter)
  const visibleItems = Array.from(items).filter(i => {
    const li = i.closest('li');
    return li && (li.style.display !== 'none');
  });
  assert.ok(visibleItems.length > 0, 'expected at least one visible item');
  assert.strictEqual(visibleItems[0].textContent.trim(), title);
});

Then('the new todo input is cleared', function () {
  const input = this.document.querySelector('.new-todo');
  assert.ok(input, 'new-todo input should exist');
  assert.strictEqual(input.value, '', 'new todo input should be empty');
});

Then('the todo is marked completed', function () {
  const firstItem = this.document.querySelector('.todo-list li:first-child');
  assert.ok(firstItem.classList.contains('completed'), 'todo should be completed');
});

Then('the todo is marked active', function () {
  const firstItem = this.document.querySelector('.todo-list li:first-child');
  assert.ok(!firstItem.classList.contains('completed'), 'todo should be active');
});

Then('all todos are completed', function () {
  const items = this.document.querySelectorAll('.todo-list li');
  assert.ok(items.length > 0, 'expected at least one todo');
  items.forEach((item, i) => {
    assert.ok(item.classList.contains('completed'), `todo ${i + 1} should be completed`);
  });
});

Then('the mark-all checkbox is checked', function () {
  const checkbox = this.document.querySelector('.toggle-all');
  assert.ok(checkbox, 'toggle-all checkbox should exist');
  assert.strictEqual(checkbox.checked, true, 'toggle-all should be checked');
});

Then('the mark-all checkbox is not checked', function () {
  const checkbox = this.document.querySelector('.toggle-all');
  assert.ok(checkbox, 'toggle-all checkbox should exist');
  assert.strictEqual(checkbox.checked, false, 'toggle-all should not be checked');
});

Then('the clear completed button is not visible', function () {
  const btn = this.document.querySelector('.clear-completed');
  if (btn) {
    const style = this.window.getComputedStyle(btn);
    assert.strictEqual(style.display, 'none', 'clear-completed button should be hidden');
  }
});

Then('the clear completed button is visible', function () {
  const btn = this.document.querySelector('.clear-completed');
  assert.ok(btn, 'clear-completed button should exist');
  const style = this.window.getComputedStyle(btn);
  assert.notStrictEqual(style.display, 'none', 'clear-completed button should be visible');
});

Then('the todo shows {string}', function (title) {
  const label = this.document.querySelector('.todo-list li:first-child label');
  assert.ok(label, 'expected a todo label');
  assert.strictEqual(label.textContent.trim(), title);
});

Then('the counter shows {string}', function (text) {
  const counter = this.document.querySelector('.todo-count');
  assert.ok(counter, 'todo-count should exist');
  assert.strictEqual(counter.textContent.trim(), text);
});

Then('localStorage contains the todos', function () {
  const data = this.localStorage.getItem('todos-vanilla');
  assert.ok(data !== null, 'localStorage should contain todos');
  const todos = JSON.parse(data);
  assert.ok(Array.isArray(todos), 'todos should be an array');
});

Then('the persisted data has {int} items', function (count) {
  const data = this.localStorage.getItem('todos-vanilla');
  assert.ok(data !== null, 'localStorage should contain todos');
  const todos = JSON.parse(data);
  assert.strictEqual(todos.length, count, `expected ${count} persisted items`);
});

Then('the first item has id {string}', function (id) {
  const data = this.localStorage.getItem('todos-vanilla');
  const todos = JSON.parse(data);
  assert.strictEqual(String(todos[0].id), id);
});

Then('the first item has title {string}', function (title) {
  const data = this.localStorage.getItem('todos-vanilla');
  const todos = JSON.parse(data);
  assert.strictEqual(todos[0].title, title);
});

Then('the first item is completed', function () {
  const data = this.localStorage.getItem('todos-vanilla');
  const todos = JSON.parse(data);
  assert.strictEqual(todos[0].completed, true);
});

Then('the second item has id {string}', function (id) {
  const data = this.localStorage.getItem('todos-vanilla');
  const todos = JSON.parse(data);
  assert.strictEqual(String(todos[1].id), id);
});

Then('the second item has title {string}', function (title) {
  const data = this.localStorage.getItem('todos-vanilla');
  const todos = JSON.parse(data);
  assert.strictEqual(todos[1].title, title);
});

Then('the second item is not completed', function () {
  const data = this.localStorage.getItem('todos-vanilla');
  const todos = JSON.parse(data);
  assert.strictEqual(todos[1].completed, false);
});

Then('the todo is not in editing mode', function () {
  const firstItem = this.document.querySelector('.todo-list li:first-child');
  assert.ok(firstItem, 'expected a todo item');
  assert.ok(!firstItem.classList.contains('editing'), 'todo should not be in editing mode');
});

