  const editInput = this.document.querySelector('.todo-list li:first-child .edit');
  if (editInput) {
    editInput.value = newTitle;
  }
});

When('the edit input loses focus', function () {
  const editInput = this.document.querySelector('.todo-list li:first-child .edit');
  if (editInput) {
    editInput.dispatchEvent(new this.window.Event('blur', { bubbles: true }));
  }
});

When('the user filters by {string}', function (filter) {
