(function () {
  'use strict';

  var STORAGE_KEY = 'todos-vanilla';
  var ENTER_KEY = 13;
  var ESCAPE_KEY = 27;

  var todos = loadTodos();
  var filter = location.hash.replace('#/', '') || 'all';
  var editingId = null;

  var todoList = document.querySelector('.todo-list');
  var newTodo = document.querySelector('.new-todo');
  var main = document.querySelector('.main');
  var footer = document.querySelector('.footer');
  var todoCount = document.querySelector('.todo-count');
  var clearCompleted = document.querySelector('.clear-completed');
  var toggleAll = document.querySelector('.toggle-all');
  var filterLinks = document.querySelectorAll('.filters a');

  function loadTodos() {
    try {
      return JSON.parse(localStorage.getItem(STORAGE_KEY)) || [];
    } catch (e) {
      return [];
    }
  }

  function saveTodos() {
    localStorage.setItem(STORAGE_KEY, JSON.stringify(todos));
  }

  function getFiltered() {
    if (filter === 'active') return todos.filter(function (t) { return !t.completed; });
    if (filter === 'completed') return todos.filter(function (t) { return t.completed; });
    return todos;
  }

  function nextId() {
    return todos.length ? Math.max.apply(null, todos.map(function (t) { return t.id; })) + 1 : 1;
  }

  function render() {
    var filtered = getFiltered();
    var activeCount = todos.filter(function (t) { return !t.completed; }).length;
    var completedCount = todos.length - activeCount;

    var hasTodos = todos.length > 0;
    main.style.display = hasTodos ? '' : 'none';
    footer.style.display = hasTodos ? '' : 'none';

    todoList.innerHTML = filtered.map(function (todo) {
      return '<li' +
        (todo.completed ? ' class="completed"' : '') +
        (editingId === todo.id ? ' class="editing"' : (todo.completed ? ' class="completed"' : '')) +
        ' data-id="' + todo.id + '">' +
        '<div class="view">' +
        '<input class="toggle" type="checkbox"' + (todo.completed ? ' checked' : '') + '>' +
        '<label>' + escapeHtml(todo.title) + '</label>' +
        '<button class="destroy"></button>' +
        '</div>' +
        '<input class="edit" value="' + escapeHtml(todo.title) + '">' +
        '</li>';
    }).join('');

    // Apply editing class properly (handles both class assignments)
    if (editingId !== null) {
      var editLi = todoList.querySelector('li[data-id="' + editingId + '"]');
      if (editLi) {
        editLi.classList.add('editing');
        var editInput = editLi.querySelector('.edit');
        if (editInput) setTimeout(function () { editInput.focus(); }, 0);
      }
    }

    var plural = activeCount === 1 ? ' item left' : ' items left';
    todoCount.innerHTML = '<strong>' + activeCount + '</strong>' + plural;

    clearCompleted.style.display = completedCount > 0 ? '' : 'none';
    toggleAll.checked = hasTodos && activeCount === 0;

    filterLinks.forEach(function (link) {
      link.classList.toggle('selected', link.getAttribute('href') === '#/' + filter || (filter === 'all' && link.getAttribute('href') === '#/'));
    });

    saveTodos();
  }

  function escapeHtml(text) {
    var div = document.createElement('div');
    div.appendChild(document.createTextNode(text));
    return div.innerHTML;
  }

  function addTodo(title) {
    title = title.trim();
    if (!title) return;
    todos.push({ id: nextId(), title: title, completed: false });
    editingId = null;
    render();
  }

  function removeTodo(id) {
    todos = todos.filter(function (t) { return t.id !== id; });
    if (editingId === id) editingId = null;
    render();
  }

  function toggleTodo(id) {
    todos.forEach(function (t) {
      if (t.id === id) t.completed = !t.completed;
    });
    render();
  }

  function toggleAllTodos(checked) {
    todos.forEach(function (t) { t.completed = checked; });
    render();
  }

  function clearCompletedTodos() {
    todos = todos.filter(function (t) { return !t.completed; });
    render();
  }

  function startEdit(id) {
    editingId = id;
    render();
  }

  function commitEdit(id, title) {
    title = title.trim();
    if (!title) {
      removeTodo(id);
      return;
    }
    todos.forEach(function (t) {
      if (t.id === id) t.title = title;
    });
    editingId = null;
    render();
  }

  function cancelEdit() {
    editingId = null;
    render();
  }

  // Event delegation
  todoList.addEventListener('click', function (e) {
    var target = e.target;
    if (target.classList.contains('toggle')) {
      var li = target.closest('li');
      if (li) toggleTodo(Number(li.getAttribute('data-id')));
    }
    if (target.classList.contains('destroy')) {
      var li = target.closest('li');
      if (li) removeTodo(Number(li.getAttribute('data-id')));
    }
  });

  todoList.addEventListener('dblclick', function (e) {
    var label = e.target;
    if (label.tagName === 'LABEL') {
      var li = label.closest('li');
      if (li) startEdit(Number(li.getAttribute('data-id')));
    }
  });

  todoList.addEventListener('blur', function (e) {
    if (e.target.classList.contains('edit') && editingId !== null) {
      commitEdit(editingId, e.target.value);
    }
  }, true);

  todoList.addEventListener('keydown', function (e) {
    if (!e.target.classList.contains('edit')) return;
    var id = Number(e.target.closest('li').getAttribute('data-id'));
    if (e.keyCode === ENTER_KEY) {
      commitEdit(id, e.target.value);
    } else if (e.keyCode === ESCAPE_KEY) {
      cancelEdit();
    }
  });

  newTodo.addEventListener('keydown', function (e) {
    if (e.keyCode === ENTER_KEY) {
      addTodo(newTodo.value);
      newTodo.value = '';
    }
  });

  toggleAll.addEventListener('change', function () {
    toggleAllTodos(toggleAll.checked);
  });

  clearCompleted.addEventListener('click', function () {
    clearCompletedTodos();
  });

  // Routing
  window.addEventListener('hashchange', function () {
    filter = location.hash.replace('#/', '') || 'all';
    editingId = null;
    render();
  });

  // Initial render
  render();
})();

